/**
 * Seeded property tests for the snapshot token codec (`HmacComponentSigner`).
 *
 * Component state is generated by a small deterministic PRNG (mulberry32) as
 * arbitrary JSON (Unicode and surrogate-pair strings, prototype-named keys
 * where the signer allows them, nesting, edge numbers). The properties:
 * `verify(sign(x))` returns `x`; any single-character edit to a token either
 * throws the value-free `SnapshotError` or verifies to the identical payload,
 * so no edit can change verified state; arbitrary text never throws anything
 * but `SnapshotError`; and a token has exactly one accepted spelling.
 */

import assert from 'node:assert/strict';
import { describe, it } from 'node:test';

import {
  HmacComponentSigner,
  SnapshotError,
  type SnapshotPayloadWithoutExpiry,
} from '../../src/server-components/snapshot.js';
import type { JsonObject, JsonValue } from '../../src/contracts/http.js';

// ---------------------------------------------------------------------------
// Seeded generator
// ---------------------------------------------------------------------------

const BASE_SEED = 0x5a40_7001;
const RUNS = 250;

/** mulberry32: a tiny, well-distributed 32-bit PRNG; same seed, same sequence. */
function mulberry32(seed: number): () => number {
  let state = seed >>> 0;
  return () => {
    state = (state + 0x6d2b79f5) >>> 0;
    let t = state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

interface Gen {
  int(min: number, max: number): number;
  pick<T>(items: readonly T[]): T;
  text(maxParts: number): string;
}

const PIECES = ['a', 'Z', '0', ' ', '"', '\\', '<', '&', '\u0000', ' ', 'é', '😀', '.', '='];

function generator(seed: number): Gen {
  const next = mulberry32(seed);
  const gen: Gen = {
    int: (min, max) => min + Math.floor(next() * (max - min + 1)),
    pick: (items) => items[Math.floor(next() * items.length)]!,
    text: (maxParts) => {
      let out = '';
      for (let i = gen.int(0, maxParts); i > 0; i -= 1) out += gen.pick(PIECES);
      return out;
    },
  };
  return gen;
}

function forAll(check: (gen: Gen) => void): void {
  for (let run = 0; run < RUNS; run += 1) {
    const caseSeed = (BASE_SEED + run) >>> 0;
    try {
      check(generator(caseSeed));
    } catch (error) {
      assert.fail(`property failed for seed ${caseSeed}: ${(error as Error).message}`);
    }
  }
}

function jsonValue(gen: Gen, depth: number): JsonValue {
  switch (depth > 3 ? gen.int(0, 3) : gen.int(0, 5)) {
    case 0:
      return gen.text(6);
    case 1:
      return gen.pick([0, -0, 1, -1, 0.5, 1e21, -1e-7, Number.MAX_SAFE_INTEGER]);
    case 2:
      return gen.pick([true, false]);
    case 3:
      return null;
    case 4:
      return Array.from({ length: gen.int(0, 3) }, () => jsonValue(gen, depth + 1));
    default:
      return stateOf(gen, depth + 1);
  }
}

function stateOf(gen: Gen, depth = 0): JsonObject {
  const state: JsonObject = {};
  for (let i = gen.int(0, 4); i > 0; i -= 1) {
    const key = gen.pick(['count', 'title', 'toString', 'valueOf', 'hasOwnProperty', gen.text(3)]);
    state[key] = jsonValue(gen, depth);
  }
  return state;
}

// ---------------------------------------------------------------------------
// Fixtures
// ---------------------------------------------------------------------------

const KEY = 'snapshot-property-key-0123456789abcdef';
const NOW = 1_700_000_000_000;
const signer = new HmacComponentSigner({ key: KEY, now: () => NOW });
const BASE64URL = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_';

function payloadOf(gen: Gen): SnapshotPayloadWithoutExpiry {
  return {
    v: 1,
    component: gen.pick(['Counter', 'Form', 'List']),
    id: `id-${gen.int(0, 1_000_000)}`,
    state: stateOf(gen),
    page: { path: gen.pick(['/', '/counter', '/a/b']), params: { id: String(gen.int(0, 99)) } },
    origin: 'https://app.example',
    subject: gen.pick([null, signer.subjectFor('session-property')]),
  };
}

function mutate(gen: Gen, token: string): string {
  const index = gen.int(0, token.length - 1);
  const character = gen.pick([...BASE64URL, '.', '=', '+', '/']);
  switch (gen.int(0, 2)) {
    case 0:
      return token.slice(0, index) + character + token.slice(index + 1);
    case 1:
      return token.slice(0, index) + token.slice(index + 1);
    default:
      return token.slice(0, index) + character + token.slice(index);
  }
}

/** Verify, returning the payload or `null` on a `SnapshotError`; anything else fails. */
function tryVerify(token: string): ReturnType<HmacComponentSigner['verify']> | null {
  try {
    return signer.verify(token);
  } catch (error) {
    assert.ok(error instanceof SnapshotError, `unexpected ${String(error)}`);
    assert.ok(!error.message.includes(KEY));
    return null;
  }
}

// ---------------------------------------------------------------------------
// Properties
// ---------------------------------------------------------------------------

describe('property: HmacComponentSigner', () => {
  it('verify(sign(payload)) returns the signed payload', () => {
    forAll((gen) => {
      const payload = payloadOf(gen);
      const verified = signer.verify(signer.sign(payload));
      assert.deepEqual(verified.state, JSON.parse(JSON.stringify(payload.state)));
      assert.equal(verified.component, payload.component);
      assert.equal(verified.id, payload.id);
      assert.deepEqual(verified.page, payload.page);
      assert.equal(verified.subject, payload.subject);
    });
  });

  it('a single-character edit throws SnapshotError or verifies to the identical payload', () => {
    forAll((gen) => {
      const token = signer.sign(payloadOf(gen));
      const original = signer.verify(token);
      for (let edit = 0; edit < 20; edit += 1) {
        const mutated = mutate(gen, token);
        if (mutated === token) continue;
        const verified = tryVerify(mutated);
        if (verified !== null) assert.deepEqual(verified, original);
      }
    });
  });

  it('throws only SnapshotError on arbitrary text', () => {
    forAll((gen) => {
      let token = '';
      for (let i = gen.int(0, 80); i > 0; i -= 1)
        token += gen.pick([...BASE64URL, '.', '=', ' ', '😀']);
      assert.equal(tryVerify(token), null);
    });
  });

  // Base64url decoding ignores the unused low bits of a segment's final
  // character, so a 43-character MAC (and a payload whose length is not a
  // multiple of 3) has several spellings that decode to the same bytes.
  // `verifyAndDecode` accepts only the canonical one, so the raw token string
  // is a canonical identifier for cache, dedupe, or audit keys.
  it('accepts exactly one spelling of a token', () => {
    forAll((gen) => {
      const token = signer.sign(payloadOf(gen));
      const last = token.at(-1)!;
      const index = BASE64URL.indexOf(last);
      // Flip the lowest bit of the MAC's final character: a padding bit in a
      // 43-character (256-bit) base64url digest.
      const respelled = token.slice(0, -1) + BASE64URL[index ^ 1]!;
      assert.equal(tryVerify(respelled), null, 're-spelled MAC verified');
    });
  });

  it('rejects a non-canonical spelling of the payload segment', () => {
    forAll((gen) => {
      const token = signer.sign(payloadOf(gen));
      const dot = token.indexOf('.');
      const payloadPart = token.slice(0, dot);
      // Only a payload whose byte length is not a multiple of 3 has unused
      // low bits in its final character.
      if (payloadPart.length % 4 === 0) {
        return;
      }
      const index = BASE64URL.indexOf(payloadPart.at(-1)!);
      const respelled = payloadPart.slice(0, -1) + BASE64URL[index ^ 1]! + token.slice(dot);
      assert.equal(tryVerify(respelled), null, 're-spelled payload verified');
    });
  });
});
